local kv = workspace.LV_KITVEG
-- agrupa masters por kit
local masters = {}
for _, p in ipairs(kv:GetChildren()) do
  if p:IsA("BasePart") then
    local base = p.Name:match("^(.-)__") or p.Name
    masters[base] = masters[base] or {}
    table.insert(masters[base], p)
  end
end
local pasta = workspace:FindFirstChild("Vegetacao")
if not pasta then pasta = Instance.new("Folder") pasta.Name = "Vegetacao" pasta.Parent = workspace end
for _, c in ipairs(pasta:GetChildren()) do c:Destroy() end
local n = 0
for _, e in ipairs(PLAN) do
  local kit, x, yv, z, rot, s = e[1], e[2], e[3], e[4], e[5], e[6]
  local parts = masters[kit]
  if parts then
    local mdl = Instance.new("Model")
    mdl.Name = kit
    for _, p in ipairs(parts) do
      local cp = p:Clone()
      cp.Parent = mdl
    end
    local cf, sz = mdl:GetBoundingBox()
    mdl.WorldPivot = CFrame.new(cf.Position - Vector3.new(0, sz.Y/2, 0))
    mdl:ScaleTo(s)
    mdl:PivotTo(CFrame.new(x, yv - 0.15, z) * CFrame.Angles(0, math.rad(-rot), 0))
    mdl.Parent = pasta
    n += 1
  end
end
return "plantados: " .. n
